import React, { useState, useRef, useEffect } from 'react'
import * as Dialog from '@radix-ui/react-dialog'
import * as Tabs from '@radix-ui/react-tabs'
import { useForm, Controller, useFieldArray } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { X, Upload, Trash2, Plus, Save, Loader2 } from 'lucide-react'
import { supabase } from '../../../lib/supabase'
import { useI18n } from '../../../i18n/I18nProvider'
import { adminButtonPrimaryClass } from '../../../utils/adminUi'

// --- Zod Schema ---
const productSchema = z.object({
    name: z.string().min(1, 'Ürün adı zorunludur'),
    sku: z.string().min(1, 'SKU zorunludur'),
    brand: z.string().optional(),
    model_code: z.string().optional(),
    category_id: z.string().optional(),
    status: z.enum(['active', 'inactive', 'out_of_stock']).default('active'),
    price: z.number().min(0).optional().nullable(),
    purchase_price: z.number().min(0).optional().nullable(),
    stock_qty: z.number().int().min(0).optional().nullable(),
    low_stock_threshold: z.number().int().min(0).optional().nullable(),
    description: z.string().optional().nullable(),
    slug: z.string().optional(),
    meta_title: z.string().optional(),
    meta_description: z.string().optional(),
    is_featured: z.boolean().default(false),
    technical_specs: z.record(z.string(), z.any()).default({}),
})

type ProductFormValues = z.infer<typeof productSchema>

interface ProductFormModalProps {
    open: boolean
    onOpenChange: (open: boolean) => void
    productId?: string | null
    onSuccess: () => void
    categories: { id: string; name: string }[]
}

// --- Image Compression Helper ---
const compressImage = async (file: File): Promise<Blob> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader()
        reader.readAsDataURL(file)
        reader.onload = (event) => {
            const img = new Image()
            img.src = event.target?.result as string
            img.onload = () => {
                const canvas = document.createElement('canvas')
                const MAX_WIDTH = 1200
                const scaleSize = MAX_WIDTH / img.width
                const newWidth = (img.width > MAX_WIDTH) ? MAX_WIDTH : img.width
                const newHeight = (img.width > MAX_WIDTH) ? (img.height * scaleSize) : img.height
                canvas.width = newWidth
                canvas.height = newHeight
                const ctx = canvas.getContext('2d')
                if (!ctx) { reject(new Error("Canvas context failed")); return }
                ctx.drawImage(img, 0, 0, newWidth, newHeight)
                canvas.toBlob((blob) => {
                    if (blob) resolve(blob)
                    else reject(new Error("Compression failed"))
                }, 'image/webp', 0.8)
            }
        }
        reader.onerror = (error) => reject(error)
    })
}

export const ProductFormModal: React.FC<ProductFormModalProps> = ({ open, onOpenChange, productId, onSuccess, categories }) => {
    const { t: _t } = useI18n()
    const [activeTab, setActiveTab] = useState('info')
    const [loading, setLoading] = useState(false)
    const [uploading, setUploading] = useState(false)

    // Images state (separate from form for easier handling)
    const [images, setImages] = useState<{ id?: string; path?: string; url: string; file?: File; isNew?: boolean }[]>([])

    // Technical Specs State (Key-Value pairs for UI)
    const [specs, setSpecs] = useState<{ key: string; value: string }[]>([])
    const [initialData, setInitialData] = useState<ProductFormValues | null>(null)

    const { register, handleSubmit, reset, formState: { errors } } = useForm<ProductFormValues>({
        resolver: zodResolver(productSchema),
        defaultValues: {
            status: 'active',
            is_featured: false,
            technical_specs: {}
        }
    })

    const loadProduct = React.useCallback(async (id: string) => {
        setLoading(true)
        try {
            // Fetch product
            const { data: product, error } = await supabase.from('products').select('*').eq('id', id).single()
            if (error) throw error
            setInitialData(product)

            // Fetch images
            const { data: imgs, error: imgError } = await supabase
                .from('product_images')
                .select('*')
                .eq('product_id', id)
                .order('sort_order')

            if (imgError) throw imgError

            // Set Form
            reset({
                name: product.name,
                sku: product.sku,
                brand: product.brand || '',
                model_code: product.model_code || '',
                category_id: product.category_id || '',
                status: product.status || 'active',
                price: product.price,
                purchase_price: product.purchase_price,
                stock_qty: product.stock_qty,
                low_stock_threshold: product.low_stock_threshold,
                description: product.description,
                slug: product.slug,
                meta_title: product.meta_title,
                meta_description: product.meta_description,
                is_featured: product.is_featured,
                technical_specs: product.technical_specs || {}
            })

            // Set Images
            const loadedImages = (imgs || []).map(img => ({
                id: img.id,
                path: img.path,
                url: `${import.meta.env.VITE_SUPABASE_URL}/storage/v1/object/public/product-images/${img.path}`,
                isNew: false
            }))
            setImages(loadedImages)

            // Set Specs
            const loadedSpecs = Object.entries(product.technical_specs || {}).map(([key, value]) => ({
                key,
                value: String(value)
            }))
            setSpecs(loadedSpecs)

        } catch (e) {
            console.error('Error loading product:', e)
            alert('Ürün yüklenirken hata oluştu')
        } finally {
            setLoading(false)
        }
    }, [reset])

    // Load Data
    useEffect(() => {
        if (open && productId) {
            loadProduct(productId)
        } else if (open && !productId) {
            reset({ status: 'active', is_featured: false, technical_specs: {} })
            setImages([])
            setSpecs([])
            setInitialData(null)
            setActiveTab('info')
        }
    }, [open, productId, loadProduct, reset])

    // --- Handlers ---

    const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            const files = Array.from(e.target.files)
            const newImages = files.map(file => ({
                url: URL.createObjectURL(file),
                file,
                isNew: true
            }))
            setImages(prev => [...prev, ...newImages])
        }
    }

    const removeImage = (index: number) => {
        setImages(prev => prev.filter((_, i) => i !== index))
    }

    const handleSpecChange = (index: number, field: 'key' | 'value', val: string) => {
        const newSpecs = [...specs]
        newSpecs[index][field] = val
        setSpecs(newSpecs)
    }

    const addSpec = () => setSpecs([...specs, { key: '', value: '' }])
    const removeSpec = (index: number) => setSpecs(specs.filter((_, i) => i !== index))

    const onSubmit = async (data: ProductFormValues) => {
        setLoading(true)
        try {
            // 1. Prepare Specs JSON
            const specsJson = specs.reduce((acc, curr) => {
                if (curr.key.trim()) acc[curr.key.trim()] = curr.value
                return acc
            }, {} as Record<string, string>)

            data.technical_specs = specsJson

            let currentProductId = productId

            // 2. Insert/Update Product
            if (currentProductId) {
                const { error } = await supabase.from('products').update(data).eq('id', currentProductId)
                if (error) throw error

                // Audit Log
                const { logAdminAction } = await import('../../../lib/audit')
                await logAdminAction(supabase, {
                    table_name: 'products',
                    row_pk: currentProductId,
                    action: 'UPDATE',
                    before: initialData,
                    after: data,
                    comment: 'Updated via Modal'
                })

            } else {
                const { data: newProd, error } = await supabase.from('products').insert(data).select('id').single()
                if (error) throw error
                currentProductId = newProd.id

                // Audit Log
                const { logAdminAction } = await import('../../../lib/audit')
                await logAdminAction(supabase, {
                    table_name: 'products',
                    row_pk: currentProductId,
                    action: 'INSERT',
                    before: null,
                    after: data,
                    comment: 'Created via Modal'
                })
            }

            // 3. Handle Images
            if (images.some(img => img.isNew) || images.length < (await fetchExistingImageCount(currentProductId))) {
                await processImages(currentProductId, data.name)
            }

            onSuccess()
            onOpenChange(false)

        } catch (e: unknown) {
            console.error('Save error:', e)
            alert(`Kaydetme hatası: ${e instanceof Error ? e.message : 'Bilinmeyen hata'}`)
        } finally {
            setLoading(false)
        }
    }

    const fetchExistingImageCount = async (pid: string) => {
        const { count } = await supabase.from('product_images').select('*', { count: 'exact', head: true }).eq('product_id', pid)
        return count || 0
    }

    const processImages = async (pid: string, productName: string) => {
        setUploading(true)
        try {
            // 1. Delete removed images from DB (and storage if possible)
            // For simplicity in this hybrid approach, we'll just sync the list.
            // Actually, a better way is to delete all and re-insert or diff.
            // Let's do a diff based on ID.

            const { data: existingImgs } = await supabase.from('product_images').select('id, path').eq('product_id', pid)
            const keptIds = images.filter(i => !i.isNew && i.id).map(i => i.id)
            const toDelete = existingImgs?.filter(ei => !keptIds.includes(ei.id)) || []

            for (const del of toDelete) {
                await supabase.from('product_images').delete().eq('id', del.id)
                await supabase.storage.from('product-images').remove([del.path])
            }

            // 2. Upload New Images
            let sortOrder = 0
            for (const img of images) {
                sortOrder++
                if (img.isNew && img.file) {
                    // Compress
                    const compressedBlob = await compressImage(img.file)
                    const ext = 'webp'
                    const filename = `prod_${pid}_${Date.now()}_${Math.random().toString(36).substring(7)}.${ext}`
                    const path = `product/${pid}/${filename}`

                    // Upload
                    const { error: upErr } = await supabase.storage.from('product-images').upload(path, compressedBlob, { contentType: 'image/webp' })
                    if (upErr) throw upErr

                    // Insert DB
                    await supabase.from('product_images').insert({
                        product_id: pid,
                        path: path,
                        sort_order: sortOrder,
                        alt: productName
                    })
                } else if (img.id) {
                    // Update sort order for existing
                    await supabase.from('product_images').update({ sort_order: sortOrder }).eq('id', img.id)
                }
            }

        } catch (e) {
            console.error('Image process error:', e)
            throw e
        } finally {
            setUploading(false)
        }
    }

    // --- UI Components ---
    const TabTrigger = ({ value, label }: { value: string, label: string }) => (
        <Tabs.Trigger
            value={value}
            className="px-4 py-2 text-sm font-medium text-gray-600 border-b-2 border-transparent data-[state=active]:border-blue-600 data-[state=active]:text-blue-600 hover:text-gray-900 transition-colors"
        >
            {label}
        </Tabs.Trigger>
    )

    return (
        <Dialog.Root open={open} onOpenChange={onOpenChange}>
            <Dialog.Portal>
                <Dialog.Overlay className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50" />
                <Dialog.Content className="fixed left-[50%] top-[50%] translate-x-[-50%] translate-y-[-50%] w-full max-w-4xl max-h-[90vh] bg-white rounded-xl shadow-2xl z-50 flex flex-col outline-none">

                    {/* Header */}
                    <div className="flex items-center justify-between p-6 border-b border-gray-100">
                        <Dialog.Title className="text-xl font-bold text-gray-900">
                            {productId ? 'Ürünü Düzenle' : 'Yeni Ürün Ekle'}
                        </Dialog.Title>
                        <Dialog.Close className="text-gray-400 hover:text-gray-600 transition-colors">
                            <X size={24} />
                        </Dialog.Close>
                    </div>

                    {/* Body */}
                    <div className="flex-1 overflow-y-auto">
                        {loading ? (
                            <div className="flex items-center justify-center h-64">
                                <Loader2 className="animate-spin text-blue-600" size={32} />
                            </div>
                        ) : (
                            <form id="product-form" onSubmit={handleSubmit(onSubmit)} className="p-6">
                                <Tabs.Root value={activeTab} onValueChange={setActiveTab}>
                                    <Tabs.List className="flex border-b border-gray-200 mb-6 overflow-x-auto">
                                        <TabTrigger value="info" label="Genel Bilgiler" />
                                        <TabTrigger value="pricing" label="Fiyat & Stok" />
                                        <TabTrigger value="images" label="Görseller" />
                                        <TabTrigger value="specs" label="Teknik Özellikler" />
                                        <TabTrigger value="seo" label="SEO" />
                                    </Tabs.List>

                                    {/* INFO TAB */}
                                    <Tabs.Content value="info" className="space-y-4">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Ürün Adı *</label>
                                                <input {...register('name')} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                                {errors.name && <span className="text-xs text-red-500">{errors.name.message}</span>}
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">SKU (Stok Kodu) *</label>
                                                <input {...register('sku')} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                                {errors.sku && <span className="text-xs text-red-500">{errors.sku.message}</span>}
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Marka</label>
                                                <input {...register('brand')} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Model Kodu</label>
                                                <input {...register('model_code')} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Kategori</label>
                                                <select {...register('category_id')} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                                                    <option value="">Seçiniz</option>
                                                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                                </select>
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Durum</label>
                                                <select {...register('status')} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                                                    <option value="active">Aktif</option>
                                                    <option value="inactive">Pasif</option>
                                                    <option value="out_of_stock">Stok Yok</option>
                                                </select>
                                            </div>
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-sm font-medium text-gray-700">Açıklama</label>
                                            <textarea {...register('description')} rows={4} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none" />
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <input type="checkbox" {...register('is_featured')} id="is_featured" className="rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                                            <label htmlFor="is_featured" className="text-sm font-medium text-gray-700">Öne Çıkan Ürün</label>
                                        </div>
                                    </Tabs.Content>

                                    {/* PRICING TAB */}
                                    <Tabs.Content value="pricing" className="space-y-4">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Satış Fiyatı (TL)</label>
                                                <input type="number" step="0.01" {...register('price', { valueAsNumber: true })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Alış Fiyatı (TL)</label>
                                                <input type="number" step="0.01" {...register('purchase_price', { valueAsNumber: true })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Stok Adedi</label>
                                                <input type="number" {...register('stock_qty', { valueAsNumber: true })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-medium text-gray-700">Kritik Stok Seviyesi</label>
                                                <input type="number" {...register('low_stock_threshold', { valueAsNumber: true })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                            </div>
                                        </div>
                                    </Tabs.Content>

                                    {/* IMAGES TAB */}
                                    <Tabs.Content value="images" className="space-y-4">
                                        <div className="border-2 border-dashed border-gray-300 rounded-xl p-8 flex flex-col items-center justify-center text-gray-500 hover:border-blue-500 hover:bg-blue-50 transition-colors cursor-pointer relative">
                                            <input type="file" multiple accept="image/*" onChange={handleImageSelect} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                                            <Upload size={32} className="mb-2" />
                                            <p className="text-sm font-medium">Resimleri buraya sürükleyin veya seçin</p>
                                            <p className="text-xs text-gray-400 mt-1">Otomatik WebP sıkıştırma uygulanır</p>
                                        </div>

                                        <div className="grid grid-cols-4 gap-4 mt-4">
                                            {images.map((img, idx) => (
                                                <div key={idx} className="relative group border rounded-lg overflow-hidden aspect-square bg-gray-50">
                                                    <img src={img.url} alt="Product" className="w-full h-full object-contain" />
                                                    <button
                                                        type="button"
                                                        onClick={() => removeImage(idx)}
                                                        className="absolute top-2 right-2 bg-red-500 text-white p-1.5 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                                    >
                                                        <Trash2 size={16} />
                                                    </button>
                                                    {idx === 0 && (
                                                        <div className="absolute bottom-0 inset-x-0 bg-blue-600 text-white text-[10px] py-1 text-center">
                                                            Kapak Görseli
                                                        </div>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </Tabs.Content>

                                    {/* SPECS TAB */}
                                    <Tabs.Content value="specs" className="space-y-4">
                                        <div className="flex justify-between items-center mb-2">
                                            <h3 className="text-sm font-medium text-gray-700">Teknik Özellikler (JSON)</h3>
                                            <button type="button" onClick={addSpec} className="text-blue-600 text-sm flex items-center gap-1 hover:underline">
                                                <Plus size={16} /> Özellik Ekle
                                            </button>
                                        </div>

                                        <div className="space-y-2">
                                            {specs.map((spec, idx) => (
                                                <div key={idx} className="flex gap-2 items-center">
                                                    <input
                                                        placeholder="Özellik Adı (örn. Güç)"
                                                        value={spec.key}
                                                        onChange={(e) => handleSpecChange(idx, 'key', e.target.value)}
                                                        className="flex-1 border rounded px-3 py-2 text-sm"
                                                    />
                                                    <input
                                                        placeholder="Değer (örn. 5kW)"
                                                        value={spec.value}
                                                        onChange={(e) => handleSpecChange(idx, 'value', e.target.value)}
                                                        className="flex-1 border rounded px-3 py-2 text-sm"
                                                    />
                                                    <button type="button" onClick={() => removeSpec(idx)} className="text-red-500 hover:bg-red-50 p-2 rounded">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            ))}
                                            {specs.length === 0 && (
                                                <div className="text-center py-8 text-gray-400 text-sm border rounded-lg border-dashed">
                                                    Henüz teknik özellik eklenmemiş.
                                                </div>
                                            )}
                                        </div>
                                    </Tabs.Content>

                                    {/* SEO TAB */}
                                    <Tabs.Content value="seo" className="space-y-4">
                                        <div className="space-y-2">
                                            <label className="text-sm font-medium text-gray-700">SEO URL (Slug)</label>
                                            <input {...register('slug')} placeholder="Otomatik oluşturulur" className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-sm font-medium text-gray-700">Meta Başlık</label>
                                            <input {...register('meta_title')} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-sm font-medium text-gray-700">Meta Açıklama</label>
                                            <textarea {...register('meta_description')} rows={3} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none" />
                                        </div>
                                    </Tabs.Content>
                                </Tabs.Root>
                            </form>
                        )}
                    </div>

                    {/* Footer */}
                    <div className="p-6 border-t border-gray-100 flex justify-end gap-3 bg-gray-50 rounded-b-xl">
                        <button
                            type="button"
                            onClick={() => onOpenChange(false)}
                            className="px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-200 rounded-lg transition-colors"
                        >
                            İptal
                        </button>
                        <button
                            type="submit"
                            form="product-form"
                            disabled={loading || uploading}
                            className={`${adminButtonPrimaryClass} flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed`}
                        >
                            {(loading || uploading) ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                            {productId ? 'Değişiklikleri Kaydet' : 'Ürünü Oluştur'}
                        </button>
                    </div>

                </Dialog.Content>
            </Dialog.Portal>
        </Dialog.Root>
    )
}

import React from 'react'
import { supabase } from '../../lib/supabase'
import AdminToolbar from '../../components/admin/AdminToolbar'
import type { Density } from '../../components/admin/ColumnsMenu'
import { adminSectionTitleClass, adminCardClass, adminTableHeadCellClass, adminTableCellClass, adminButtonPrimaryClass } from '../../utils/adminUi'
import { useI18n } from '../../i18n/I18nProvider'
import { formatCurrency } from '../../i18n/format'
import { ProductFormModal } from '../../components/admin/products/ProductFormModal'

interface ProductRow {
  id: string
  name: string
  sku: string
  brand?: string | null
  status?: string | null
  category_id?: string | null
  price?: number | null
  purchase_price?: number | null
  stock_qty?: number | null
  low_stock_threshold?: number | null
  is_featured?: boolean | null
}

interface CategoryOpt { id: string; name: string }

const AdminProductsPage: React.FC = () => {
  const { t, lang } = useI18n()
  const [rows, setRows] = React.useState<ProductRow[]>([])
  const [cats, setCats] = React.useState<CategoryOpt[]>([])
  const [q, setQ] = React.useState('')
  const [debouncedQ, setDebouncedQ] = React.useState('')
  const [loading, setLoading] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)

  // Modal State
  const [isModalOpen, setIsModalOpen] = React.useState(false)
  const [editingId, setEditingId] = React.useState<string | null>(null)

  // Pagination
  const PAGE_SIZE = 50
  const [page, setPage] = React.useState(1)
  const [total, setTotal] = React.useState(0)

  // Toolbar filtreleri
  const [selectedCategoryFilter, setSelectedCategoryFilter] = React.useState<string>('')
  const [statusFilter, setStatusFilter] = React.useState<{ active: boolean; inactive: boolean; out_of_stock: boolean }>({ active: false, inactive: false, out_of_stock: false })
  const [featuredOnly, setFeaturedOnly] = React.useState<boolean>(false)

  // Columns & density
  const STORAGE_KEY = 'toolbar:products'
  const [visibleCols, setVisibleCols] = React.useState<{ image: boolean; name: boolean; sku: boolean; category: boolean; status: boolean; price: boolean; stock: boolean; actions: boolean }>({ image: true, name: true, sku: true, category: true, status: true, price: true, stock: true, actions: true })
  const [density, setDensity] = React.useState<Density>('comfortable')
  const _defaultThreshold = React.useState<number | null>(null)
  const [covers, setCovers] = React.useState<Record<string, string>>({})

  React.useEffect(() => { try { const c = localStorage.getItem(`${STORAGE_KEY}:cols`); if (c) setVisibleCols(prev => ({ ...prev, ...JSON.parse(c) })); const d = localStorage.getItem(`${STORAGE_KEY}:density`); if (d === 'compact' || d === 'comfortable') setDensity(d as Density) } catch { } }, [])
  React.useEffect(() => { try { localStorage.setItem(`${STORAGE_KEY}:cols`, JSON.stringify(visibleCols)) } catch { } }, [visibleCols])
  React.useEffect(() => { try { localStorage.setItem(`${STORAGE_KEY}:density`, density) } catch { } }, [density])
  const headPad = density === 'compact' ? 'px-2 py-2' : ''
  const cellPad = density === 'compact' ? 'px-2 py-2' : ''

  // Persist sort settings
  type SortKey = 'name' | 'sku' | 'category' | 'status' | 'price' | 'stock'
  const SORT_KEY_STORAGE = `${STORAGE_KEY}:sortKey`
  const SORT_DIR_STORAGE = `${STORAGE_KEY}:sortDir`
  const [sortKey, setSortKey] = React.useState<SortKey>(() => {
    try { const v = localStorage.getItem(SORT_KEY_STORAGE) as SortKey | null; if (v === 'name' || v === 'sku' || v === 'category' || v === 'status' || v === 'price' || v === 'stock') return v; } catch { }
    return 'name'
  })
  const [sortDir, setSortDir] = React.useState<'asc' | 'desc'>(() => {
    try { const v = localStorage.getItem(SORT_DIR_STORAGE) as 'asc' | 'desc' | null; if (v === 'asc' || v === 'desc') return v } catch { }
    return 'asc'
  })
  React.useEffect(() => { try { localStorage.setItem(SORT_KEY_STORAGE, sortKey) } catch { } }, [sortKey, SORT_KEY_STORAGE])
  React.useEffect(() => { try { localStorage.setItem(SORT_DIR_STORAGE, sortDir) } catch { } }, [sortDir, SORT_DIR_STORAGE])

  const load = React.useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      // Build products query with server-side filters and pagination
      let query = supabase
        .from('products')
        .select('id,name,sku,brand,status,category_id,price,purchase_price,stock_qty,low_stock_threshold,is_featured,slug', { count: 'exact' })

      // Filters
      if (selectedCategoryFilter) query = query.eq('category_id', selectedCategoryFilter)
      if (featuredOnly) query = query.eq('is_featured', true)
      const anyStatus = statusFilter.active || statusFilter.inactive || statusFilter.out_of_stock
      if (anyStatus) {
        const statuses: string[] = []
        if (statusFilter.active) statuses.push('active')
        if (statusFilter.inactive) statuses.push('inactive')
        if (statusFilter.out_of_stock) statuses.push('out_of_stock')
        if (statuses.length === 1) query = query.eq('status', statuses[0])
        else if (statuses.length > 1) query = query.in('status', statuses)
      }
      const term = debouncedQ.trim()
      if (term) {
        const like = `%${term}%`
        query = query.or(`name.ilike.${like},sku.ilike.${like},brand.ilike.${like},slug.ilike.${like}`)
      }

      // Sorting (only supported keys)
      const sortableMap: Record<SortKey, string | null> = { name: 'name', sku: 'sku', category: null, status: 'status', price: 'price', stock: 'stock_qty' }
      const col = sortableMap[sortKey]
      if (col) query = query.order(col, { ascending: sortDir === 'asc' })
      else query = query.order('name', { ascending: true })

      // Pagination
      const from = (page - 1) * PAGE_SIZE
      const to = from + PAGE_SIZE - 1
      const { data, error, count } = await query.range(from, to)
      if (error) throw error
      const list = (data || []) as ProductRow[]
      setRows(list)
      setTotal(typeof count === 'number' ? count : 0)

      // Categories + settings
      const [c, s] = await Promise.all([
        supabase.from('categories').select('id,name').order('name', { ascending: true }),
        supabase.from('inventory_settings').select('default_low_stock_threshold').maybeSingle(),
      ])
      if (c.error) throw c.error
      setCats((c.data || []) as CategoryOpt[])
      if (!s.error) _defaultThreshold[1](((s.data as { default_low_stock_threshold?: number | null } | null)?.default_low_stock_threshold ?? null) as number | null)

      // Cover images for current page
      const ids = list.map(x => x.id)
      if (ids.length > 0) {
        const { data: imgs } = await supabase.from('product_images').select('product_id,path,sort_order').in('product_id', ids).order('sort_order', { ascending: true })
        const map: Record<string, string> = {}
          ; (imgs as { product_id: string; path: string; sort_order: number }[] | null | undefined)?.forEach(r => { if (map[r.product_id] == null) map[r.product_id] = r.path })
        setCovers(map)
      }
    } catch (e) {
      setError((e as Error).message || t('admin.products.toasts.loadFailed'))
      setRows([])
      setTotal(0)
    } finally {
      setLoading(false)
    }
  }, [selectedCategoryFilter, featuredOnly, statusFilter, debouncedQ, sortKey, sortDir, page, t])

  React.useEffect(() => { load() }, [load])

  React.useEffect(() => {
    const t = setTimeout(() => setDebouncedQ(q.trim()), 300)
    return () => clearTimeout(t)
  }, [q])

  // Server-side filtered rows already; keep as identity
  const filtered = React.useMemo(() => rows, [rows])

  const handleCreate = () => {
    setEditingId(null)
    setIsModalOpen(true)
  }

  const handleEdit = (id: string) => {
    setEditingId(id)
    setIsModalOpen(true)
  }

  const handleModalSuccess = () => {
    load()
    // Modal will be closed by the modal itself or we can close it here if needed, 
    // but the modal calls onSuccess then onOpenChange(false) usually.
    // Actually our modal implementation calls onSuccess then onOpenChange(false).
    // So we just need to reload data.
  }

  const remove = async (id: string) => {
    if (!confirm(t('admin.products.confirm.deleteProduct'))) return
    try {
      const before = rows.find(r => r.id === id) || null
      const { error } = await supabase.from('products').delete().eq('id', id)
      if (error) throw error
      const { logAdminAction } = await import('../../lib/audit')
      await logAdminAction(supabase, { table_name: 'products', row_pk: id, action: 'DELETE', before, after: null, comment: 'remove product' })
      await load()
    } catch (e) {
      alert(t('admin.products.toasts.deleteFailed', { msg: ((e as Error).message || String(e)) }))
    }
  }

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) setSortDir(d => d === 'asc' ? 'desc' : 'asc')
    else { setSortKey(key); setSortDir('asc') }
    setPage(1)
  }
  const sortIndicator = (key: SortKey) => sortKey !== key ? '' : (sortDir === 'asc' ? '▲' : '▼')

  const sorted = React.useMemo(() => {
    const arr = [...filtered]
    arr.sort((a, b) => {
      const dir = sortDir === 'asc' ? 1 : -1
      switch (sortKey) {
        case 'name': return dir * a.name.localeCompare(b.name, 'tr')
        case 'sku': return dir * a.sku.localeCompare(b.sku, 'tr')
        case 'category': {
          const an = cats.find(c => c.id === a.category_id)?.name || ''
          const bn = cats.find(c => c.id === b.category_id)?.name || ''
          return dir * an.localeCompare(bn, 'tr')
        }
        case 'status': return dir * (String(a.status || '').localeCompare(String(b.status || ''), 'tr'))
        case 'price': return dir * (((a.price ?? -Infinity) as number) - ((b.price ?? -Infinity) as number))
        case 'stock': return dir * (((a.stock_qty ?? -Infinity) as number) - ((b.stock_qty ?? -Infinity) as number))
        default: return 0
      }
    })
    return arr
  }, [filtered, sortKey, sortDir, cats])

  const statusBadge = (s?: string | null) => {
    const v = (s || '').toLowerCase()
    if (v === 'active') return <span className="px-2 py-0.5 text-xs rounded bg-green-100 text-green-700">{t('admin.products.statusLabels.active')}</span>
    if (v === 'inactive') return <span className="px-2 py-0.5 text-xs rounded bg-gray-200 text-gray-700">{t('admin.products.statusLabels.inactive')}</span>
    if (v === 'out_of_stock') return <span className="px-2 py-0.5 text-xs rounded bg-orange-100 text-orange-700">{t('admin.products.statusLabels.out_of_stock')}</span>
    return <span className="px-2 py-0.5 text-xs rounded bg-gray-100 text-gray-600">-</span>
  }

  const [importPreview, setImportPreview] = React.useState<{ header: string[]; rows: Record<string, string>[]; total: number } | null>(null)
  const [importRows, setImportRows] = React.useState<Record<string, string>[] | null>(null)

  const ColumnsMenu = React.useMemo(() => React.lazy(() => import('../../components/admin/ColumnsMenu')), [])
  const ExportMenu = React.useMemo(() => React.lazy(() => import('../../components/admin/ExportMenu')), [])

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className={adminSectionTitleClass}>{t('admin.titles.products') ?? 'Ürünler'}</h1>
        <button onClick={handleCreate} className={`${adminButtonPrimaryClass} flex items-center gap-2`}>
          <span>+</span> {t('admin.products.edit.actions.new') ?? 'Yeni Ürün'}
        </button>
      </div>

      <AdminToolbar
        storageKey="toolbar:products"
        sticky
        search={{ value: q, onChange: (v) => { setQ(v); setPage(1) }, placeholder: t('admin.search.products') ?? 'ürün adı/SKU/marka/slug ara', focusShortcut: '/' }}
        select={{
          value: selectedCategoryFilter,
          onChange: setSelectedCategoryFilter,
          title: t('admin.products.toolbar.categoryTitle') ?? 'Kategori',
          options: [{ value: '', label: t('admin.products.toolbar.allCategories') ?? 'Tüm Kategoriler' }, ...cats.map(c => ({ value: c.id, label: c.name }))],
        }}
        chips={[
          { key: 'active', label: t('admin.products.statusLabels.active'), active: statusFilter.active, onToggle: () => setStatusFilter(s => ({ ...s, active: !s.active })) },
          { key: 'inactive', label: t('admin.products.statusLabels.inactive'), active: statusFilter.inactive, onToggle: () => setStatusFilter(s => ({ ...s, inactive: !s.inactive })) },
          { key: 'out_of_stock', label: t('admin.products.statusLabels.out_of_stock'), active: statusFilter.out_of_stock, onToggle: () => setStatusFilter(s => ({ ...s, out_of_stock: !s.out_of_stock })) },
        ]}
        toggles={[{ key: 'featured', label: t('admin.products.toggles.featuredOnly'), checked: featuredOnly, onChange: setFeaturedOnly }]}
        onClear={() => { setQ(''); setSelectedCategoryFilter(''); setStatusFilter({ active: false, inactive: false, out_of_stock: false }); setFeaturedOnly(false); setPage(1) }}
        recordCount={total}
        rightExtra={(
          <div className="flex items-center gap-2">
            <input id="prod-import-input" type="file" accept=".csv,text/csv" className="hidden" onChange={async (e) => {
              const f = e.target.files?.[0]
              if (!f) return
              const text = await f.text()
              const lines = text.replace(/^\ufeff/, '').split(/\r?\n/).filter(l => l.trim().length > 0)
              const split = (s: string) => s.split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/).map(v => v.replace(/^"|"$/g, '').replace(/""/g, '"'))
              const header = split(lines[0]).map(h => h.trim().toLowerCase())
              const rows = lines.slice(1).map(l => { const cells = split(l); const obj: Record<string, string> = {}; header.forEach((h, i) => obj[h] = cells[i] || ''); return obj })
              setImportRows(rows)
              setImportPreview({ header, rows: rows.slice(0, 10), total: rows.length })
            }} />
            <button onClick={() => document.getElementById('prod-import-input')?.click()} className="px-3 md:h-12 h-11 inline-flex items-center gap-2 rounded-md border border-light-gray bg-white hover:border-primary-navy text-sm whitespace-nowrap">{t('admin.products.import.button')}</button>
            <React.Suspense fallback={<button className="px-3 md:h-12 h-11 inline-flex items-center gap-2 rounded-md border border-light-gray bg-white text-sm opacity-70" disabled>Görünüm…</button>}>
              <ColumnsMenu
                columns={[
                  { key: 'image', label: t('admin.products.table.image'), checked: visibleCols.image, onChange: (v) => setVisibleCols(s => ({ ...s, image: v })) },
                  { key: 'name', label: t('admin.products.table.name'), checked: visibleCols.name, onChange: (v) => setVisibleCols(s => ({ ...s, name: v })) },
                  { key: 'sku', label: t('admin.products.table.sku'), checked: visibleCols.sku, onChange: (v) => setVisibleCols(s => ({ ...s, sku: v })) },
                  { key: 'category', label: t('admin.products.table.category'), checked: visibleCols.category, onChange: (v) => setVisibleCols(s => ({ ...s, category: v })) },
                  { key: 'status', label: t('admin.products.table.status'), checked: visibleCols.status, onChange: (v) => setVisibleCols(s => ({ ...s, status: v })) },
                  { key: 'price', label: t('admin.products.table.price'), checked: visibleCols.price, onChange: (v) => setVisibleCols(s => ({ ...s, price: v })) },
                  { key: 'stock', label: t('admin.products.table.stock'), checked: visibleCols.stock, onChange: (v) => setVisibleCols(s => ({ ...s, stock: v })) },
                  { key: 'actions', label: t('admin.products.table.actions'), checked: visibleCols.actions, onChange: (v) => setVisibleCols(s => ({ ...s, actions: v })) },
                ]}
                density={density}
                onDensityChange={setDensity}
              />
            </React.Suspense>
            <React.Suspense fallback={<button className="px-3 md:h-12 h-11 inline-flex items-center gap-2 rounded-md border border-light-gray bg-white text-sm opacity-70" disabled>İndir…</button>}>
              <ExportMenu
                items={[
                  {
                    key: 'csv', label: t('admin.products.export.csvLabel'), onSelect: () => {
                      const cols = ['id', 'name', 'sku', 'category_id', 'status', 'price', 'stock_qty']
                      const header = cols.join(',')
                      const lines = sorted.map(r => [
                        r.id, `"${(r.name || '').replace(/"/g, '""')}"`, r.sku, r.category_id || '', r.status || '', r.price != null ? String(r.price) : '', r.stock_qty != null ? String(r.stock_qty) : ''
                      ].join(','))
                      const csv = '\ufeff' + [header, ...lines].join('\n')
                      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
                      const url = URL.createObjectURL(blob)
                      const a = document.createElement('a')
                      a.href = url
                      a.download = 'products.csv'
                      a.click()
                      URL.revokeObjectURL(url)
                    }
                  }
                ]}
              />
            </React.Suspense>
          </div>
        )}
      />

      {importPreview && (
        <div className={`${adminCardClass} p-4`}>
          <div className="mb-2 text-sm text-industrial-gray">{t('admin.products.import.previewTitle', { total: importPreview.total }) ?? `CSV Önizleme (ilk 10 satır) — Toplam: ${importPreview.total}`}</div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-gray-50">
                <tr>
                  {importPreview.header.map(h => (<th key={h} className="p-2 border-b text-left">{h}</th>))}
                </tr>
              </thead>
              <tbody>
                {importPreview.rows.map((r, idx) => (
                  <tr key={idx} className="border-b">
                    {importPreview.header.map(h => (<td key={h} className="p-2">{r[h]}</td>))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="mt-3 flex items-center gap-2">
            <button className="px-3 h-10 rounded-md border border-light-gray bg-white hover:border-primary-navy text-xs" onClick={() => { setImportPreview(null); setImportRows(null); }}>{t('admin.products.import.close')}</button>
            <button className="px-3 h-10 rounded-md border border-light-gray bg-white text-xs" onClick={() => {
              const h = (importPreview?.header || [])
              const required = ['name', 'sku']
              const hasRequired = required.every(k => h.includes(k))
              const okCount = (importPreview?.rows || []).filter(r => r['name'] && r['sku']).length
              alert(t('admin.products.import.dryRunResult', { status: t(`admin.products.import.${hasRequired ? 'statusComplete' : 'statusMissing'}`), ok: okCount, total: importPreview?.total || 0 }))
            }}>{t('admin.products.import.dryRun')}</button>
            <button className="px-3 h-10 rounded-md bg-primary-navy text-white text-xs" onClick={async () => {
              if (!importRows || !importPreview) return alert(t('admin.products.import.needCsv'))
              const h = importPreview.header
              if (!h.includes('sku') || !h.includes('name')) { alert(t('admin.products.import.minColumns')); return }
              const mapCategorySlugToId = (slug: string) => {
                const s = (slug || '').toLowerCase().trim()
                const found = cats.find(c => c.name.toLowerCase() === s)
                return found?.id || null
              }
              const payloads: { sku: string; name: string; model_code?: string | null; brand?: string; status?: string; price?: number; stock_qty?: number; low_stock_threshold?: number | null; category_id?: string | null }[] = []
              for (const r of importRows) {
                if (!r['sku'] || !r['name']) continue
                const p: { sku: string; name: string; model_code?: string | null; brand?: string; status?: string; price?: number; stock_qty?: number; low_stock_threshold?: number | null; category_id?: string | null } = {
                  sku: r['sku'].trim(),
                  name: r['name'].trim(),
                }
                if (r['model_code']) p.model_code = r['model_code'].trim()
                else if (r['model']) p.model_code = r['model'].trim()
                if (r['brand']) p.brand = r['brand'].trim()
                if (r['status']) p.status = r['status'].trim()
                if (r['price']) p.price = Number(r['price'])
                if (r['stock_qty']) p.stock_qty = Number(r['stock_qty'])
                if (r['low_stock_threshold']) p.low_stock_threshold = Number(r['low_stock_threshold'])
                if (r['category_id']) p.category_id = r['category_id'] || null
                else if (r['category_slug'] || r['category']) p.category_id = mapCategorySlugToId(r['category_slug'] || r['category'])
                payloads.push(p)
              }
              if (payloads.length === 0) { alert(t('admin.products.import.noneFound')); return }
              try {
                // chunked upsert by sku
                let ok = 0, fail = 0
                for (let i = 0; i < payloads.length; i += 100) {
                  const chunk = payloads.slice(i, i + 100)
                  const { error } = await supabase.from('products').upsert(chunk, { onConflict: 'sku' })
                  if (error) { console.warn('import upsert error', error); fail += chunk.length } else ok += chunk.length
                }
                alert(t('admin.products.import.done', { ok, fail }))
                await load()
              } catch (e) {
                alert(t('admin.products.import.error', { msg: ((e as Error).message || String(e)) }))
              }
            }}>{t('admin.products.import.writeButton')}</button>
          </div>
        </div>
      )}

      {/* Table */}
      <div className={`${adminCardClass} overflow-hidden`}>
        {error && <div className="p-3 text-red-600 text-sm border-b border-red-100">{error}</div>}
        <div className="p-2 flex items-center justify-between text-sm text-steel-gray">
          <div>{t('admin.ui.total') ?? 'Toplam'}: {total}</div>
          <div className="flex items-center gap-2">
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page <= 1} className="px-3 py-1 rounded border border-light-gray bg-white disabled:opacity-50">{t('admin.ui.prev')}</button>
            <span>{t('admin.ui.pageLabel', { page, pages: Math.max(1, Math.ceil(total / PAGE_SIZE)) })}</span>
            <button onClick={() => setPage(p => p + 1)} disabled={page >= Math.max(1, Math.ceil(total / PAGE_SIZE))} className="px-3 py-1 rounded border border-light-gray bg-white disabled:opacity-50">{t('admin.ui.next')}</button>
          </div>
        </div>
        <table className="w-full">
          <thead className="bg-gray-50">
            <tr>
              {visibleCols.image && (
                <th className={`${adminTableHeadCellClass} ${headPad}`}>{t('admin.products.table.image')}</th>
              )}
              {visibleCols.name && (
                <th className={`${adminTableHeadCellClass} ${headPad}`}>
                  <button type="button" className="hover:underline" onClick={() => toggleSort('name')}>{t('admin.products.table.name')} {sortIndicator('name')}</button>
                </th>
              )}
              {visibleCols.sku && (
                <th className={`${adminTableHeadCellClass} ${headPad}`}>
                  <button type="button" className="hover:underline" onClick={() => toggleSort('sku')}>{t('admin.products.table.sku')} {sortIndicator('sku')}</button>
                </th>
              )}
              {visibleCols.category && (
                <th className={`${adminTableHeadCellClass} ${headPad}`}>
                  <button type="button" className="hover:underline" onClick={() => toggleSort('category')}>{t('admin.products.table.category')} {sortIndicator('category')}</button>
                </th>
              )}
              {visibleCols.status && (
                <th className={`${adminTableHeadCellClass} ${headPad}`}>
                  <button type="button" className="hover:underline" onClick={() => toggleSort('status')}>{t('admin.products.table.status')} {sortIndicator('status')}</button>
                </th>
              )}
              {visibleCols.price && (
                <th className={`${adminTableHeadCellClass} ${headPad} text-right`}>
                  <button type="button" className="hover:underline" onClick={() => toggleSort('price')}>{t('admin.products.table.price')} {sortIndicator('price')}</button>
                </th>
              )}
              {visibleCols.stock && (
                <th className={`${adminTableHeadCellClass} ${headPad} text-right`}>
                  <button type="button" className="hover:underline" onClick={() => toggleSort('stock')}>{t('admin.products.table.stock')} {sortIndicator('stock')}</button>
                </th>
              )}
              {visibleCols.actions && <th className={`${adminTableHeadCellClass} ${headPad}`}>{t('admin.products.table.actions')}</th>}
            </tr>
          </thead>
          <tbody>
            {loading && rows.length === 0 ? (
              <tr><td className="p-4" colSpan={7}>{t('admin.ui.loading')}</td></tr>
            ) : filtered.length === 0 ? (
              <tr><td className="p-4" colSpan={7}>{t('admin.ui.noRecords')}</td></tr>
            ) : (
              sorted.map(r => (
                <tr key={r.id} className="border-b border-light-gray/60">
                  {visibleCols.image && (
                    <td className={`${adminTableCellClass} ${cellPad}`}>
                      {covers[r.id] ? (
                        <img src={`${import.meta.env.VITE_SUPABASE_URL}/storage/v1/object/public/product-images/${covers[r.id]}`} alt="" className="w-10 h-10 object-cover rounded" />
                      ) : (
                        <div className="w-10 h-10 bg-gray-100 rounded" />
                      )}
                    </td>
                  )}
                  {visibleCols.name && <td className={`${adminTableCellClass} ${cellPad}`}>{r.name}</td>}
                  {visibleCols.sku && <td className={`${adminTableCellClass} ${cellPad}`}>{r.sku}</td>}
                  {visibleCols.category && <td className={`${adminTableCellClass} ${cellPad}`}>{cats.find(c => c.id === r.category_id)?.name || '-'}</td>}
                  {visibleCols.status && <td className={`${adminTableCellClass} ${cellPad}`}>{statusBadge(r.status)}</td>}
                  {visibleCols.price && <td className={`${adminTableCellClass} ${cellPad} text-right`}>{r.price != null ? formatCurrency(Number(r.price), lang) : '-'}</td>}
                  {visibleCols.stock && <td className={`${adminTableCellClass} ${cellPad} text-right`}>{(r.stock_qty != null ? Number(r.stock_qty) : null) ?? '-'}</td>}
                  {visibleCols.actions && (
                    <td className={`${adminTableCellClass} ${cellPad}`}>
                      <div className="flex items-center gap-2 whitespace-nowrap">
                        <button className="px-2 py-1 rounded border text-xs" onClick={() => handleEdit(r.id)}>{t('admin.ui.edit')}</button>
                        <button className="px-2 py-1 rounded border text-xs text-red-600" onClick={() => remove(r.id)}>{t('admin.ui.delete')}</button>
                      </div>
                    </td>
                  )}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <ProductFormModal
        open={isModalOpen}
        onOpenChange={setIsModalOpen}
        productId={editingId}
        onSuccess={handleModalSuccess}
        categories={cats.map(c => ({ id: c.id, name: c.name }))}
      />
    </div>
  )
}

export default AdminProductsPage
